'use strict';
(function(){
 const fields=[['transitShare','Public transport share (%)',0,100,1],['busCount','Available buses',0,200,1],['busSeats','Seats per bus',1,100,1],['busTrips','Arrival trips per bus',1,20,1],['gateWidth','Entrance width (m)',.5,50,.5],['crossingWidth','Crossing width (m)',.5,30,.5],['uncertainty','Attendance uncertainty (±%)',0,50,1],['shuttleRate','Shuttle cost per bus (₹)',0,1000000,100],['parkingRate','Cost per extra space (₹)',0,100000,10],['marshals','Traffic marshals in B',0,1000,1],['marshalRate','Cost per marshal (₹)',0,100000,100],['budget','Planning budget (₹)',0,100000000,1000]];
 let extra={customVenue:null,entrance:null,trafficCounts:{},stops:[],otherEvents:[]},placing=null,overlay=null,uncertaintyCache={};
 const panel=$('advanced-planning');panel.innerHTML=`<div class="section-heading"><div><div class="eyebrow">ADVANCED PLANNING / EVIDENCE & OPTIONS</div><h2>Build a plan you can explain.</h2></div><button class="button lime" id="apply-planning">Update plan</button></div><div class="planning-tabs"><a href="#location-tools">Location & evidence</a><a href="#people-tools">People & transport</a><a href="#cost-tools">Budget & uncertainty</a></div><div class="advanced-grid"><section id="location-tools"><h3>Choose the event and its entrance</h3><p>Place pins inside the study boundary. Entrance routing snaps to a nearby major-road node.</p><div class="planning-buttons"><button class="button light" id="place-venue">Place venue</button><button class="button light" id="place-entrance">Place entrance</button><button class="button light" id="place-stop">Add proposed stop</button><button class="button light" id="cancel-place">Cancel placement</button><button class="button light" id="clear-stops">Clear stops</button></div><p id="pin-status" role="status"></p><h3>Traffic counts · CSV import</h3><p>Upload road_id, vehicles_per_hour, source and date. Uploaded counts replace background demand on matching segments only. Counts are user-supplied, not independently verified.</p><div class="planning-buttons"><button class="button light" id="csv-template">Download CSV template</button><label class="button light" for="traffic-file">Import traffic CSV</label><input id="traffic-file" type="file" accept=".csv,text/csv" hidden><button class="button light" id="clear-counts">Use synthetic counts</button></div><p id="count-status" role="status"></p><h3>Nearby events</h3><p>Up to 3 events in the same study area. Car share and occupancy are shared; shuttles apply to the primary event only. Parking supply is pooled for comparison.</p><div id="nearby-events"></div><button class="button light" id="add-event">Add nearby event</button></section><section id="people-tools"><h3>People & public transport</h3><p>Primary-event estimates. Non-car attendees include public transport and other modes. Stops are proposed, not verified bus services.</p><div class="planning-inputs">${fields.slice(0,6).map(inputHTML).join('')}</div><div id="people-results"></div><div id="stop-results"></div></section><section id="cost-tools"><h3>Budget & attendance uncertainty</h3><p>Editable planning assumptions, not supplier quotes or statistical confidence intervals.</p><div class="planning-inputs">${fields.slice(6).map(inputHTML).join('')}</div><div id="budget-results"></div><div id="uncertainty-results"></div></section></div><div class="evidence-strip" id="evidence-summary"></div><div class="share-box"><h3>Share a cloud snapshot</h3><p>Anyone with the link can view these inputs, uploaded traffic counts and readiness records (including names and comments). Snapshots are independent copies; later edits do not update an existing link.</p><button class="button dark" id="share-advanced">Save snapshot & create link</button><label for="share-url">Shareable URL</label><input id="share-url" readonly placeholder="Your link will appear here"><button class="button light" id="copy-share">Copy link</button><p id="share-status" role="status"></p></div>`;
 function inputHTML([key,label,min,max,step]){return `<div><label for="plan-${key}">${label}</label><input id="plan-${key}" type="number" min="${min}" max="${max}" step="${step}" value="${PlanningModel.defaults[key]}"></div>`;}
 function read(){const value={...extra};for(const [key]of fields)value[key]=+$('plan-'+key).value;value.otherEvents=[...document.querySelectorAll('.nearby-row')].map(row=>({name:row.querySelector('[data-key=name]').value,venue:row.querySelector('[data-key=venue]').value,attendance:+row.querySelector('[data-key=attendance]').value,offset:+row.querySelector('[data-key=offset]').value}));return value;}
 function fill(v){v=PlanningModel.normalize(v);extra={customVenue:v.customVenue||null,entrance:v.entrance||null,trafficCounts:v.trafficCounts,stops:v.stops,otherEvents:v.otherEvents};for(const [key]of fields)$('plan-'+key).value=v[key];renderEventRows();}
 function renderEventRows(){$('nearby-events').replaceChildren();extra.otherEvents.forEach((event,i)=>{const row=document.createElement('div');row.className='nearby-row';row.innerHTML=`<label>Event name<input data-key="name" maxlength="60"></label><label>Location<select data-key="venue"><option value="plaza">Sector 17 Plaza</option><option value="grounds">Parade Ground</option></select></label><label>Attendance<input data-key="attendance" type="number" min="0" max="15000"></label><label>Starts relative to primary (hours)<input data-key="offset" type="number" min="-6" max="6"></label><button class="button light" type="button">Remove event</button>`;for(const k of ['name','venue','attendance','offset'])row.querySelector(`[data-key=${k}]`).value=event[k];row.querySelector('button').onclick=()=>{extra.otherEvents=read().otherEvents;extra.otherEvents.splice(i,1);renderEventRows();};$('nearby-events').append(row);});}
 function drawOverlay(){if(!leaflet)return;if(!overlay)overlay=L.layerGroup().addTo(leaflet);overlay.clearLayers();L.rectangle([[30.731,76.770],[30.749,76.791]],{weight:1,dashArray:'5 6',fill:false,color:'#9e83d3',interactive:false}).addTo(overlay);const pin=(point,label,color)=>L.circleMarker(point,{radius:8,fillColor:color,color:'#fff',weight:2,fillOpacity:1}).addTo(overlay).bindTooltip(label);if(snapshot.customVenue)pin(snapshot.customVenue,'Custom event','#9b76cb');if(snapshot.entrance)pin(snapshot.entrance,'Chosen entrance','#4c9fb0');snapshot.stops.forEach((point,i)=>{pin(point,'Proposed stop '+(i+1),'#d99740');L.polyline([point,results[current].venue.point],{color:'#d99740',dashArray:'3 7',weight:2,interactive:false}).addTo(overlay);});snapshot.otherEvents.forEach(e=>{const venue=CityData.venues.find(v=>v.id===e.venue);const label=document.createElement('span');label.textContent=e.name+' · '+e.attendance+' attendees';pin(venue.point,label,'#c05e95');});}
 function render(){const r=results[current],p=r.planning;if(!p)return;const v=PlanningModel.normalize(snapshot);$('count-status').textContent=`${p.measured} / ${UrbanModel.roads.length} segments use uploaded observations. Remaining segments use synthetic counts.`;$('pin-status').textContent=placing?`Click the map to place ${placing}.`:`${v.customVenue?'Custom venue placed. ':''}${v.entrance?'Entrance chosen. ':''}${v.stops.length} proposed stops.`;
 $('people-results').innerHTML=`<div class="planning-result"><strong>${p.pedestrians.peoplePerMinute} people/min</strong><span>Peak primary-event arrivals</span></div><p>Entrance pressure: <b>${p.pedestrians.entranceLoad}%</b> of assumed throughput. Crossing pressure: <b>${p.pedestrians.crossingLoad}%</b>. ${p.pedestrians.entranceLoad>100||p.pedestrians.crossingLoad>100?'Review access widths and stagger arrivals.':'Below the model thresholds; verify actual crowd conditions.'}</p><p>Transit demand: <b>${fmt(p.transitPeople)} people</b> · seat supply: <b>${fmt(p.transitCapacity)}</b> · shortfall: <b>${fmt(p.transitShortfall)}</b>.</p><small>Assumes 30 people/min/m at entrances, 25 at crossings, and 60% crossing use. These are illustrative assumptions, not crowd-safety standards.</small>`;
 $('stop-results').innerHTML='<h4>Proposed stops & walking distance</h4>'+(p.walks.length?p.walks.map((w,i)=>`<p>Stop ${i+1}: ${w.metres} m · about ${w.minutes} min walking.</p>`).join(''):'<p>Add stops on the map to compare access.</p>')+'<small>Straight-line distances at 4.5 km/h; actual walkable routes and crossings are not verified.</small>';
 const a=results.a.planning,b=results.b.planning;$('budget-results').innerHTML=`<table><tr><th>Incremental cost</th><th>A</th><th>B</th></tr>${Object.keys(b.costs).map(k=>`<tr><td>${k}</td><td>₹${fmt(a.costs[k])}</td><td>₹${fmt(b.costs[k])}</td></tr>`).join('')}<tr><th>Total</th><td>₹${fmt(a.totalCost)}</td><td>₹${fmt(b.totalCost)}</td></tr></table><p>${b.totalCost<=v.budget?'Within budget':'Over budget'} by ₹${fmt(Math.abs(v.budget-b.totalCost))}. A has no added interventions; base event costs are excluded.</p>`;
 const key=JSON.stringify(snapshot);if(uncertaintyCache.key!==key)uncertaintyCache={key,rows:PlanningModel.uncertainty(v)};$('uncertainty-results').innerHTML=`<h4>Scenario B · attendance sensitivity</h4><div class="table-wrap"><table><tr><th>Case</th><th>Cars</th><th>Travel (min)</th><th>Spaces short</th></tr>${uncertaintyCache.rows.map(x=>`<tr><td>${x.label}</td><td>${fmt(x.cars)}</td><td>${fmt(x.travel)}</td><td>${fmt(x.shortage)}</td></tr>`).join('')}</table></div><small>Attendance varies by ±${v.uncertainty}% across all events; other assumptions stay fixed.</small>`;
 $('evidence-summary').textContent=`Mapped: OpenStreetMap roads and places. Observed: ${p.measured} user-uploaded traffic counts. Assumed: capacities, mode shares, throughput and costs. Estimated: routes, demand, crowd pressure and budgets. ${v.otherEvents.length+1} events included; pedestrian/transit estimates are for the primary event.`;drawOverlay();}
 function report(){return `<section><h2>Advanced planning</h2><p>${escapeHTML($('evidence-summary').textContent)}</p><h3>Event group</h3><table><tr><th>Event</th><th>Location</th><th>Attendees</th><th>Start offset</th></tr>${results.b.planning.events.map(e=>`<tr><td>${escapeHTML(e.name)}</td><td>${escapeHTML(e.venue)}</td><td>${e.attendees}</td><td>${e.offset} hours</td></tr>`).join('')}</table><h3>People & transport · selected scenario</h3>${$('people-results').innerHTML}${$('stop-results').innerHTML}<h3>Budget comparison</h3>${$('budget-results').innerHTML}${$('uncertainty-results').innerHTML}<h3>Traffic observations</h3><p>${escapeHTML($('count-status').textContent)}</p>${Object.entries(snapshot.trafficCounts).map(([id,c])=>`<p>Road ${id}: ${c.volume} vehicles/h; ${escapeHTML(c.source)}, ${escapeHTML(c.date)}</p>`).join('')}</section>`;}
 window.PlanningUI={read,fill,render,report};
 $('apply-planning').onclick=()=>{current='b';run();};panel.addEventListener('input',()=>{$('form-note').textContent='Planning inputs changed. Update plan to refresh results.';});
 for(const mode of ['venue','entrance','stop'])$('place-'+mode).onclick=()=>{placing=mode;$('view').value='geo';setView();$('pin-status').textContent='Click inside the outlined map area to place '+mode;notify('Click the map to place '+mode);window.AppPages?.reveal($('geo-map'));$('geo-map').scrollIntoView({behavior:'smooth',block:'center'});};
 $('cancel-place').onclick=()=>{placing=null;render();};$('clear-stops').onclick=()=>{extra.stops=[];run();};
 if(leaflet)leaflet.on('click',e=>{if(!placing)return;const point=[+e.latlng.lat.toFixed(6),+e.latlng.lng.toFixed(6)];if(!PlanningModel.inside(point))return notify('Choose a point inside the study boundary.');if(placing==='venue'){extra.customVenue=point;extra.entrance=null;$('venue').value='custom';}if(placing==='entrance'){extra.entrance=point;if(!extra.customVenue)extra.customVenue=CityData.venues.find(v=>v.id===$('venue').value)?.point||point;$('venue').value='custom';}if(placing==='stop'){if(extra.stops.length>=5)return notify('Maximum five proposed stops.');extra.stops=[...extra.stops,point];}placing=null;run();});
 $('add-event').onclick=()=>{extra.otherEvents=read().otherEvents;if(extra.otherEvents.length>=3)return notify('Maximum three nearby events.');extra.otherEvents.push({name:'Nearby event '+(extra.otherEvents.length+1),venue:'grounds',attendance:1000,offset:0});renderEventRows();};
 $('csv-template').onclick=()=>download('traffic-count-template.csv','road_id,vehicles_per_hour,source,date\n'+UrbanModel.roads[0].id+',500,Replace with your count source,2026-10-02\n','text/csv');
 $('traffic-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error('CSV limit is 100 KB.');const counts=PlanningModel.parseCSV(await file.text());extra.trafficCounts=counts;run();notify('Traffic counts imported. Review their source and date.');}catch(error){notify(error.message);}finally{e.target.value='';}};$('clear-counts').onclick=()=>{extra.trafficCounts={};run();};
 async function share(){const button=$('share-advanced');try{const plan=readInputs();button.disabled=true;$('share-status').textContent='Saving snapshot…';const response=await fetch('/api/scenarios',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:3,plan})});if(!response.ok)throw Error((await response.json().catch(()=>({}))).error||'Cloud sharing is unavailable. Your inputs are unchanged; export a JSON file instead.');const data=await response.json();$('share-url').value=new URL('?plan='+data.id,location.origin).href;$('share-status').textContent='Snapshot saved. Anyone with this link can open a copy.';}catch(error){$('share-status').textContent=error.message;}finally{button.disabled=false;}}
 $('share-plan').onclick=share;$('share-advanced').onclick=share;$('copy-share').onclick=async()=>{if(!$('share-url').value)return notify('Create a link first.');try{await navigator.clipboard.writeText($('share-url').value);notify('Link copied.');}catch{$('share-url').select();notify('Select and copy the link from the field.');}};
 fill(snapshot);run();
 const shared=new URLSearchParams(location.search).get('plan');if(shared)(async()=>{try{if(!/^[a-f0-9]{64}$/.test(shared))throw Error('Invalid shared-plan link.');const response=await fetch('/api/scenarios/'+shared);if(!response.ok)throw Error('This cloud snapshot could not be loaded.');const data=await response.json();fillInputs(PlanningModel.validate(data.plan));run();$('share-url').value=location.href;$('share-status').textContent='Shared snapshot loaded. Your edits create a separate copy.';notify('Shared plan loaded.');}catch(error){$('share-status').textContent=error.message;}})();
})();
